/**
 * Content model shared by the built-in JSON content (content/) and the
 * Sanity documents (sanity/schemaTypes). Keep both in sync.
 */
export type SiteImage = {
  /** Path under /public (built-in content) or absolute URL (Sanity CDN). */
  src: string;
  alt: string;
  width?: number;
  height?: number;
  /** Base64 blur placeholder (generated by scripts/images.ts). */
  blurDataURL?: string;
  /** Focal point for object-fit: cover crops, as CSS object-position (e.g. "center 20%"). */
  focus?: string;
};

export type Seo = {
  title?: string;
  description?: string;
  ogImage?: SiteImage;
  noindex?: boolean;
  canonical?: string;
};

export type Faq = { q: string; a: string };
export type Link = { label: string; href: string; description?: string };
export type Feature = { title: string; text: string; icon?: string };
export type Step = { title: string; text: string };

export type ServiceCategory = "cosmetic" | "restorative" | "surgical" | "holistic" | "preventive";

export type ServiceCard = { title: string; text: string; image?: SiteImage };

/**
 * Service page content in the Ideal Dental Solutions structure, filled from
 * the original Valencia Smile Expert page text (scripts/build-services.ts).
 */
export type Service = {
  slug: string;
  path: string;
  parentPath: string;
  category: ServiceCategory;
  name: string;
  shortDescription: string;
  seo: { title: string; description: string; noindex?: boolean };
  /** Photo hero: title, subtitle, intro paragraph over a full-bleed image. */
  hero: { h1: string; subtitle: string; text: string; image: SiteImage };
  /** Light intro: heading + paragraphs (the page's opening section). */
  intro: { heading: string; paragraphs: string[] };
  /** Dark section: heading, intro, photo and an accordion of items (treatment types, benefits). */
  understanding: { heading: string; intro: string; image: SiteImage; items: ServiceCard[]; bullets?: string[] };
  /** Why choose us: heading, intro and photo cards. */
  why: { heading: string; intro: string; cards: ServiceCard[] };
  /** Dark process section: numbered steps. */
  process: { heading: string; intro: string; steps: ServiceCard[] };
  /** Full-bleed banner: who is a good candidate. */
  candidate: { heading: string; text: string; bullets: string[]; image: SiteImage };
  /** Optional pre/post care columns. */
  care?: { heading: string; intro?: string; before: string[]; after: string[]; cards?: ServiceCard[] };
  /** Comparison tables flattened on the live site (first row = header). */
  tables?: { heading: string; rows: string[][]; text?: string }[];
  /** Any remaining sections from the page, printed as text blocks. */
  extra: { heading: string; paragraphs: string[]; bullets: string[]; cards: ServiceCard[] }[];
  faqs: Faq[];
  related: string[];
  cta: { heading: string; text: string; buttonLabel: string };
  flags?: string[];
};

export type PostCategory = "Dental Implants" | "Oral Surgery" | "Restorative Dentistry" | "Cosmetic Dentistry" | "Preventive Care" | "Patient Guides";

export type Post = {
  slug: string;
  path: string;
  title: string;
  seoTitle: string;
  description: string;
  excerpt: string;
  category: PostCategory;
  tags: string[];
  datePublished: string;
  dateModified: string;
  author: string;
  image: string;
  imageAlt: string;
  keyTakeaways: string[];
  /** Markdown (built-in) — rendered through lib/markdown.ts. Sanity stores Portable Text in bodyPT. */
  body: string;
  bodyPT?: unknown[];
  faq: Faq[];
  relatedServices: string[];
  relatedPosts: string[];
  flags?: string[];
};

export type Person = {
  slug: string;
  name: string;
  credentials?: string;
  role: string;
  image: SiteImage;
  bio: string[];
  highlights?: string[];
  sameAs?: string[];
};

export type Testimonial = {
  id: string;
  author: string;
  text: string;
  rating: number;
  source: "Google";
  when?: string;
  avatar?: SiteImage;
  url?: string;
};

export type BeforeAfterCase = {
  id: string;
  title: string;
  treatment: string;
  before: SiteImage;
  after: SiteImage;
  note?: string;
};

export type LegalPage = {
  slug: string;
  path: string;
  title: string;
  updated?: string;
  body: string; // markdown
  seo: Seo;
};

/* ---------- Flexible page sections ---------- */

export type HeroSection = { _type: "hero"; eyebrow?: string; heading: string; lead?: string; primary?: Link; secondary?: Link; image?: SiteImage; variant?: "home" | "page" | "landing"; trust?: boolean };
export type IntroSplitSection = { _type: "introSplit"; eyebrow?: string; heading: string; body: string[]; image: SiteImage; imageSide?: "left" | "right"; cta?: Link };
export type FeatureGridSection = { _type: "featureGrid"; eyebrow?: string; heading: string; lead?: string; items: Feature[]; columns?: 2 | 3 | 4; dark?: boolean };
export type ServiceCategoriesSection = { _type: "serviceCategories"; eyebrow?: string; heading: string; lead?: string; categories: { title: string; text: string; href?: string; items: Link[] }[] };
export type GallerySection = { _type: "beforeAfter"; eyebrow?: string; heading: string; lead?: string; caseIds?: string[] };
export type DoctorSection = { _type: "doctor"; eyebrow?: string; heading: string; quote?: string; body: string[]; image: SiteImage; cta?: Link; stats?: { label: string; value: string }[] };
export type ReviewsSection = { _type: "reviews"; eyebrow?: string; heading: string; lead?: string; ids?: string[]; trust?: boolean };
export type FaqSection = { _type: "faq"; eyebrow?: string; heading: string; lead?: string; items: Faq[]; schema?: boolean };
export type VisitSection = { _type: "visit"; eyebrow?: string; heading: string; lead?: string; showMap?: boolean };
export type CtaSection = { _type: "cta"; eyebrow?: string; heading: string; text?: string; primary?: Link; secondary?: Link; image?: SiteImage };
export type RichTextSection = { _type: "richText"; heading?: string; body: string; narrow?: boolean };
export type TeamSection = { _type: "team"; eyebrow?: string; heading: string; lead?: string; slugs?: string[] };
export type PhotoGridSection = { _type: "photoGrid"; eyebrow?: string; heading: string; lead?: string; images: SiteImage[] };
export type ValuesSection = { _type: "values"; eyebrow?: string; heading: string; lead?: string; items: Feature[] };
export type FormSection = { _type: "form"; eyebrow?: string; heading: string; lead?: string; formName: string; services?: boolean };
export type ServicesHubSection = { _type: "servicesHub" };
export type InsuranceSection = { _type: "insurance"; heading?: string; text?: string };
export type OfferSection = { _type: "offer"; eyebrow?: string; heading: string; text: string; bullets?: string[]; fine?: string; cta?: Link };

export type TreatmentPickerSection = { _type: "treatmentPicker"; eyebrow?: string; heading: string; lead?: string; options: { id: string; label: string; title: string; text: string; links: Link[] }[] };
export type FirstVisitSection = { _type: "firstVisit"; eyebrow?: string; heading: string; lead?: string; steps: Step[]; cta?: Link; note?: string };
export type TechExplainerSection = { _type: "techExplainer"; eyebrow?: string; heading: string; lead?: string; dark?: boolean; image?: SiteImage; items: { title: string; text: string; forYou: string; icon?: string }[] };
export type DoctorIntroSection = { _type: "doctorIntro"; eyebrow?: string; heading: string; body: string[]; image: SiteImage; points?: string[]; cta?: Link };
export type FocusAreasSection = { _type: "focusAreas"; eyebrow?: string; heading: string; lead?: string; areas: { title: string; text: string; image: SiteImage; link: Link; points?: string[] }[] };

export type ServiceShowcaseSection = { _type: "serviceShowcase"; eyebrow?: string; heading: string; lead?: string; slugs: string[] };
export type StatBandSection = { _type: "statBand" };
export type MarqueeSection = { _type: "marquee"; items: string[]; dark?: boolean };
export type CtaBannerSection = { _type: "ctaBanner"; heading: string; text: string; image?: SiteImage; buttonLabel?: string };

export type PageSection =
  | HeroSection | IntroSplitSection | FeatureGridSection | ServiceCategoriesSection | GallerySection | DoctorSection
  | ReviewsSection | FaqSection | VisitSection | CtaSection | RichTextSection | TeamSection | PhotoGridSection
  | ValuesSection | FormSection | ServicesHubSection | InsuranceSection | OfferSection
  | TreatmentPickerSection | FirstVisitSection | TechExplainerSection | DoctorIntroSection | FocusAreasSection
  | ServiceShowcaseSection | StatBandSection | CtaBannerSection | MarqueeSection;

export type Page = {
  slug: string;
  path: string;
  title: string;
  seo: Seo;
  sections: PageSection[];
  breadcrumb?: string;
};

export type NavGroup = { title: string; description?: string; href?: string; items: Link[] };
export type Navigation = {
  header: { label: string; href: string; mega?: boolean }[];
  serviceGroups: NavGroup[];
  footer: { title: string; items: Link[] }[];
  legal: Link[];
};
